import heapq


def fire_arrivals(request):
    """Return earliest ignition tick per cell, or None for walls/unreached.

    Fire spreads orthogonally; entering a neighbor v costs spread_cost[v].
    Seeds start at their own time. Road closures do not affect fire.
    """
    grid = request["grid"]
    h = len(grid)
    w = len(grid[0])
    spread = request["spread_cost"]

    dist = {}
    queue = []
    for s in request["fire_seeds"]:
        r, c = s["r"], s["c"]
        t = s["time"]
        if grid[r][c] != "#" and t < dist.get((r, c), float("inf")):
            dist[(r, c)] = t
            heapq.heappush(queue, (t, r, c))

    while queue:
        t, r, c = heapq.heappop(queue)
        if dist.get((r, c)) != t:
            continue
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != "#":
                nt = t + spread[nr][nc]
                if nt < dist.get((nr, nc), float("inf")):
                    dist[(nr, nc)] = nt
                    heapq.heappush(queue, (nt, nr, nc))

    return [
        [None if grid[r][c] == "#" else dist.get((r, c)) for c in range(w)]
        for r in range(h)
