    dist[(start[0], start[1], release)] = 0
    while queue:
        r, c, t = queue.popleft()
        d = dist[(r, c, t)]
        if (r, c) == goal:
            continue
        if t >= max_ticks:
            continue
        for nr, nc in [(r, c)] + _neighbors(request, r, c):
            if _safe(request, hazard, nr, nc, t + 1):
                ns = (nr, nc, t + 1)
                if ns not in dist:
