        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] != "#":
            out.append((nr, nc))
    return out


def _release_of(request, pid):
    for ev in request["evacuees"]:
        if ev["id"] == pid:
            return ev["release"]
    return 0


def _shortest_path(request, hazard, e, shelter):
    """BFS shortest safe path from person start to shelter cell.

    Returns list of [r,c] cells from release cell through shelter cell, or
    None if unreachable within max_ticks.
    """
    start = (e["r"], e["c"])
    goal = (shelter["r"], shelter["c"])
    release = e["release"]
    max_ticks = request["max_ticks"]

    if not _safe(request, hazard, start[0], start[1], release):
        return None

    start_state = (start[0], start[1], release)
    queue = deque([start_state])
    prev = {start_state: None}
    visited = {start_state}

    while queue:
        r, c, t = queue.popleft()
        if (r, c) == goal:
            path = []
            state = (r, c, t)
            while state is not None:
                path.append([state[0], state[1]])
                state = prev[state]
            path.reverse()
            return path
        if t >= max_ticks:
            continue
        if _safe(request, hazard, r, c, t + 1):
            ns = (r, c, t + 1)
            if ns not in visited:
                visited.add(ns)
                prev[ns] = (r, c, t)
                queue.append(ns)
        for nr, nc in _neighbors(request, r, c):
            if _safe(request, hazard, nr, nc, t + 1):
                ns = (nr, nc, t + 1)
                if ns not in visited:
                    visited.add(ns)
                    prev[ns] = (r, c, t)
                    queue.append(ns)
    return None


def _enumerate_paths(request, hazard, e, shelter):
    """Enumerate a bounded set of candidate paths from person to shelter.

    Returns list of paths (each a list of [r,c]). Includes shortest paths and
    paths with limited waiting, bounded to keep search tractable.
    """
    start = (e["r"], e["c"])
    goal = (shelter["r"], shelter["c"])
    release = e["release"]
    max_ticks = request["max_ticks"]

    if not _safe(request, hazard, start[0], start[1], release):
        return []

    dist = {}
    queue = deque([(start[0], start[1], release)])
    dist[(start[0], start[1], release)] = 0
    while queue:
        r, c, t = queue.popleft()
        d = dist[(r, c, t)]
        if (r, c) == goal:
            continue
        if t >= max_ticks:
            continue
        for nr, nc in [(r, c)] + _neighbors(request, r, c):
            if _safe(request, hazard, nr, nc, t + 1):
                ns = (nr, nc, t + 1)
                if ns not in dist:
                    dist[ns] = d + 1
                    queue.append(ns)

    min_arrival = None
    for t in range(release, max_ticks + 1):
        if (goal[0], goal[1], t) in dist:
            min_arrival = t
