from runtime import build, read

from packages.analysis.hazard_model import fire_arrivals
from packages.analysis.joint_evacuation import plan_routes


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    hazard = fire_arrivals(request)
    plan = plan_routes(request, hazard)
    return {
        "max_saved": plan["max_saved"],
        "total_arrival": plan["total_arrival"],
        "fire_arrival": hazard,
        "evacuees": plan["evacuees"],
        "shelters": plan["shelters"],
    }


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

