:hazard-model","llm:joint-evac"]}},"tool":"report_frontier_state"},{"arguments":{"mode":"parallel","offer_id":"v2-f29ed3284c72","plan":{"acceptance_policy":{"minimum_score":0,"operator":"all","validators":[]},"failure_policy":"continue","join_policy":"all_terminal","policy_version":"semserve.dag-policy.v1","subtasks":[{"completion_contract":{"required_artifact_kinds":["file"],"required_artifact_paths":["packages/analysis/hazard_model.py"],"required_test_targets":[]},"depends_on":[],"id":"hazard-model","input_refs":[],"inputs":{},"task":"Implement fire_arrivals Dijkstra over grid with seed times and spread costs; walls None."},{"completion_contract":{"required_artifact_kinds":["file"],"required_artifact_paths":["packages/analysis/joint_evacuation.py"],"required_test_targets":[]},"depends_on":[],"id":"joint-evac","input_refs":[],"inputs":{},"task":"Implement joint lexicographic evacuation planner with conflicts, capacity, closures, safety."}]},"reason":"Two independent implementation units with disjoint owned files and concrete inputs are ready."},"result":{"accepted":[],"all_required_accepted":false,"artifacts":[{"artifact_id":"artifact-48ca75f9a2ecf44b","branch_id":"v2-f29ed3284c72-0","content":"{"packages/analysis/hazard_model.py": "import heapq\n\n\ndef fire_arrivals(request):\n    \"\"\"Return earliest ignition tick per cell, or None for walls/unreached.\n\n    Fire spreads orthogonally; entering a neighbor v costs spread_cost[v].\n    Seeds start at their own time. Road closures do not affect fire.\n    \"\"\"\n    grid = request[\"grid\"]\n    h = len(grid)\n    w = len(grid[0])\n    spread = request[\"spread_cost\"]\n\n    dist = {}\n    queue = []\n    for s in request[\"fire_seeds\"]:\n        r, c = s[\"r\"], s[\"c\"]\n        t = s[\"time\"]\n        if grid[r][c] != \"#\" and t < dist.get((r, c), float(\"inf\")):\n            dist[(r, c)] = t\n            heapq.heappush(queue, (t, r, c))\n\n    while queue:\n        t, r, c = heapq.heappop(queue)\n        if dist.get((r, c)) != t:\n            continue\n        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):\n            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != \"#\":\n                nt = t + spread[nr][nc]\n                if nt < dist.get((nr, nc), float(\"inf\")):\n                    dist[(nr, nc)] = nt\n                    heapq.heappush(queue, (nt, nr, nc))\n\n    return [\n        [None if grid[r][c] == \"#\" else dist.get((r, c)) for c in range(w)]\n        for r in range(h)\n    ]\n"}","content_sha256":"[HASH]","delivery_verified":true,"materialized_files":{"packages/analysis/hazard_model.py":"[HASH]"},"tested_targets":[],"validated":false},{"artifact_id":"artifact-054498bea9d9bee3","branch_id":"v2-f29ed3284c72-1","content":"{"packages/analysis/joint_evacuation.py": "\"\"\"Joint evacuation planner.\n\nFinds a globally optimal legal joint witness for the evacuation problem\ndescribed in SPEC.md. The objective is lexicographic: first maximize the\nnumber of assigned people, then minimize the sum of their absolute arrival\ntimes.\n\"\"\"\n\nfrom collections import defaultdict, deque\n\n\ndef _safe(request, hazard, r, c, t):\n    \"\"\"Return True if cell (r,c) may be occupied at integer time t.\"\"\"\n    grid = request[\"grid\"]\n    if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):\n        return False\n    if grid[r][c] == \"#\":\n        return False\n    fire = hazard[r][c]\n    if fire is not None and t >= fire:\n        return False\n    for cl in request[\"closures\"]:\n        if cl[\"r\"] == r and cl[\"c\"] == c and cl[\"start\"] <= t <= cl[\"end\"]:\n            return False\n    return True\n\n\ndef _neighbors(request, r, c):\n    grid = request[\"grid\"]\n    out = []\n    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n        nr, nc = r + dr, c + dc\n        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] != \"#\":\n            out.append((nr, nc))\n    return out\n\n\ndef _release_of(reques