{"packages/analysis/joint_evacuation.py": """"Joint evacuation planner.

Finds a globally optimal legal joint witness for the evacuation problem
described in SPEC.md. The objective is lexicographic: first maximize the
number of assigned people, then minimize the sum of their absolute arrival
times.
"""

from collections import defaultdict, deque


def _safe(request, hazard, r, c, t):
    """Return True if cell (r,c) may be occupied at integer time t."""
    grid = request["grid"]
    if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
        return False
    if grid[r][c] == "#":
        return False
    fire = hazard[r][c]
    if fire is not None and t >= fire:
        return False
    for cl in request["closures"]:
        if cl["r"] == r and cl["c"] == c and cl["start"] <= t <= cl["end"]:
            return False
    return True


def _neighbors(request, r, c):
    grid = request["grid"]
    out = []
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] != "#":
            out.append((nr, nc))
    return out


def _release_of(request, pid):
    for ev in request["evacuees"]:
        if ev["id"] == pid:
            return ev["release"]
    return 0


def _shortest_path(request, hazard, e, shelter):
    """BFS shortest safe path from person start to shelter cell.

    Returns list of [r,c] cells from release cell through shelter cell, or
    None if unreachable within max_ticks.
    """
    start = (e["r"], e["c"])
    goal = (shelter["r"], shelter["c"])
    release = e["release"]
    max_ticks = request["max_ticks"]

    if not _safe(request, hazard, start[0], start[1], release):
        return None

    start_state = (start[0], start[1], release)
    queue = deque([start_state])
    prev = {start_state: None}
    visited = {start_state}

    while queue:
        r, c, t = queue.popleft()
        if (r, c) == goal:
            path = []
            state = (r, c, t)
            while state is not None:
                path.append([state[0], state[1]])
                state = prev[state]
            path.reverse()
            return path
        if t >= max_ticks:
            continue
        if _safe(request, hazard, r, c, t + 1):
            ns = (r, c, t + 1)
            if ns not in visited:
                visited.add(ns)
                prev[ns] = (r, c, t)
                queue.append(ns)
        for nr, nc in _neighbors(request, r, c):
            if _safe(request, hazard, nr, nc, t + 1):
                ns = (nr, nc, t + 1)
                if ns not in visited:
                    visited.add(ns)
                    prev[ns] = (r, c, t)
                    queue.append(ns)
    return None


def _enumerate_paths(request, hazard, e, shelter):
    """Enumerate a bounded set of candidate paths from person to shelter.

    Returns list of paths (each a list of [r,c]). Includes shortest paths and
    paths with limited waiting, bounded to keep search tractable.
    """
    start = (e["r"], e["c"])
    goal = (shelter["r"], shelter["c"])
    release = e["release"]
    max_ticks = request["max_ticks"]

    if not _safe(request, hazard, start[0], start[1], release):
        return []

    dist = {}
    queue = deque([(start[0], start[1], release)])
    dist[(start[0], start[1], release)] = 0
    while queue:
        r, c, t = queue.popleft()
        d = dist[(r, c, t)]
        if (r, c) == goal:
            continue
        if t >= max_ticks:
            continue
        for nr, nc in [(r, c)] + _neighbors(request, r, c):
            if _safe(request, hazard, nr, nc, t + 1):
                ns = (nr, nc, t + 1)
                if ns not in dist:
                    dist[ns] = d + 1
                    queue.append(ns)

    min_arrival = None
    for t in range(release, max_ticks + 1):
        if (goal[0], goal[1], t) in dist:
            min_arrival = t
            break
    if min_arrival is None:
        return []

    extra_wait = 2
    max_arrival = min(min_arrival + extra_wait, max_ticks)

    paths = []

    def dfs_path(r, c, t, path):
        if len(paths) >= 200:
            return
        if (r, c) == goal:
            if t >= min_arrival:
                paths.append([list(p) for p in path])
            return
        if t >= max_arrival:
            return
        for nr, nc in [(r, c)] + _neighbors(request, r, c):
            if _safe(request, hazard, nr, nc, t + 1):
                path.append((nr, nc))
                dfs_path(nr, nc, t + 1, path)
                path.pop()

    dfs_path(start[0], start[1], release, [(start[0], start[1])])

    if not paths:
        sp = _shortest_path(request, hazard, e, shelter)
        if sp is not None:
            paths = [sp]
    return paths


def _conflicts(request, assignment, new_pid, new_path):
    """Check whether new_path for new_pid conflicts with assigned people."""
    new_release = _release_of(request, new_pid)
    for pid, (sid, arrival, path) in assignment.items():
        release = _release_of(request, pid)
        for i, cell in enumerate(path):
            t = release + i
            new_i = t - new_release
            if 0 <= new_i < len(new_path):
                if tuple(new_path[new_i]) == tuple(cell):
                    return True
        for i in range(len(path) - 1):
            t = release + i
            a = tuple(path[i])
            b = tuple(path[i + 1])
            new_i = t - new_release
            if 0 <= new_i < len(new_path) - 1:
                na = tuple(new_path[new_i])
                nb = tuple(new_path[new_i + 1])
                if a == nb and b == na and a != b:
                    return True
    return False


def _joint_dfs(request, hazard, subset, shelter_by_id):
    """Joint DFS assigning each person a path, checking conflicts."""
    candidates = {}
    for pid in subset:
        e = None
        for ev in request["evacuees"]:
            if ev["id"] == pid:
                e = ev
                break
        cands = []
        for sid in e["eligible_shelters"]:
            s = shelter_by_id[sid]
            for path in _enumerate_paths(request, hazard, e, s):
                arrival = e["release"] + len(path) - 1
                if arrival <= request["max_ticks"] and \
                        s["opens"] <= arrival < s["closes"]:
                    cands.append((sid, arrival, path))
        if not cands:
            return None
        candidates[pid] = cands

    order = sorted(subset, key=lambda p: len(candidates[p]))
    best = [None]

    def dfs(idx, assignment, used_capacity, total):
        if best[0] is not None and total > best[0][0]:
            return
        if idx == len(order):
            if best[0] is None or total < best[0][0]:
                best[0] = (total, dict(assignment))
            return
        pid = order[idx]
        for sid, arrival, path in candidates[pid]:
            if used_capacity[sid] >= shelter_by_id[sid]["capacity"]:
                continue
            if _conflicts(request, assignment, pid, path):
                continue
            assignment[pid] = (sid, arrival, path)
            used_capacity[sid] += 1
            dfs(idx + 1, assignment, used_capacity, total + arrival)
            used_capacity[sid] -= 1
            del assignment[pid]

    dfs(0, {}, defaultdict(int), 0)
    return best[0]


def plan_routes(request, hazard):
    """Return the joint evacuation report dict.

    The returned dict has keys max_saved, total_arrival, evacuees, shelters.
    """
    evacuees = request["evacuees"]
    shelters = request["shelters"]
    shelter_by_id = {s["id"]: s for s in shelters}

    ids = [e["id"] for e in evacuees]
    n = len(ids)

    best_saved = 0
    best_total = None
    best_assignment = {}

    for mask in range(1 << n):
        count = bin(mask).count("1")
        if count < best_saved:
            continue
        subset = [ids[i] for i in range(n) if mask & (1 << i)]
        result = _joint_dfs(request, hazard, subset, shelter_by_id)
        if result is None:
            continue
        total, assignment = result
        if count > best_saved or (count == best_saved and
                                  (best_total is None or total < best_total)):
            best_saved = count
            best_total = total
            best_assignment = assignment

    used = defaultdict(int)
    for pid, (sid, arrival, path) in best_assignment.items():
        used[sid] += 1

    out_evacuees = []
    for e in evacuees:
        if e["id"] in best_assignment:
            sid, arrival, path = best_assignment[e["id"]]
            out_evacuees.append({
                "id": e["id"],
                "status": "assigned",
                "shelter": sid,
                "arrival": arrival,
                "path": path,
            })
        else:
            out_evacuees.append({
                "id": e["id"],
                "status": "unassigned",
                "shelter": None,
                "arrival": None,
                "path": [],
            })

    out_shelters = [
        {"id": s["id"], "used": used[s["id"]], "capacity": s["capacity"]}
        for s in shelters
    ]

    return {
        "max_saved": best_saved,
        "total_arrival": best_total if best_total is not None else 0,
        "evacuees": out_evacuees,
        "shelters": out_shelters,
    }
